 tools.jackson.databind.node.ObjectNode compositionNode(tools.jackson.databind.JsonNode row){return (tools.jackson.databind.node.ObjectNode)row.path("composition");}
 void setReferences(tools.jackson.databind.node.ObjectNode row,List<String> ids){var c=compositionNode(row);((tools.jackson.databind.node.ObjectNode)c.path("center")).put("recipeId",ids.isEmpty()?"":ids.getFirst());c.put("stapleRecipeId",ids.size()>1?ids.get(1):"");var sides=c.putArray("sideRecipeIds");ids.stream().skip(2).forEach(sides::add);}
 String withoutRole(String value,String id){var tree=json.readTree(value);for(var row:tree.path("slots")){var c=compositionNode(row);if(id.equals("new-side"))c.putArray("sideRecipeIds");else if(id.equals("new-rice"))c.put("stapleRecipeId","");else ((tools.jackson.databind.node.ObjectNode)c.path("center")).put("recipeId","");}return json.writeValueAsString(tree);}
 @Test void repairMissingSideAndStapleWithAndWithoutExistingCandidates(){
  for(boolean populated:List.of(false,true))for(String missing:List.of("new-side","new-rice")){
   jdbc.update("DELETE FROM my_recipes");jdbc.update("DELETE FROM recipe_library");
   if(populated){var r=new MyRecipeService.Snapshot("기존 후보",1,10,List.of("채소 50g"),List.of("조리한다."));String data=json.writeValueAsString(r),id=MyRecipeService.fingerprint(data);jdbc.update("INSERT INTO recipe_library(recipe_id,recipe_data,period_kind) VALUES(?,?,?)",id,data,"main");jdbc.update("INSERT INTO my_recipes VALUES(?,?,?)",1,id,"PRIVATE-OVERRIDE");}
   int before=client.calls;String valid=output(7,List.of("breakfast","lunch","dinner"));client.responses.add(withoutRole(valid,missing));client.responses.add(valid);
   var result=service.generate(1,request(UUID.randomUUID(),7,List.of("breakfast","lunch","dinner")),Map.of());assertEquals(21,result.slots().size());assertEquals(before+2,client.calls);
   var repair=json.readTree(client.input);assertEquals("repair_composition",repair.path("task").asText());assertTrue(repair.path("validationFeedback").asText().contains("COMBINATION_MISSING"));assertEquals(populated?1:0,repair.path("originalInput").path("recipes").size());assertEquals(populated?1:0,repair.path("originalInput").path("savedRecipeIds").size());assertFalse(client.input.contains("PRIVATE-OVERRIDE"));
  }
 }
