 @Test void allFourFebruaryBlocksRepairAndCoverEveryRequestedMeal(){
  LocalDate first=LocalDate.of(2027,2,1);int count=0;
  for(int block=0;block<4;block++){
   var tree=json.readTree(output(7,List.of("breakfast","lunch","dinner")));int index=0;for(var slot:tree.path("slots"))((tools.jackson.databind.node.ObjectNode)slot).put("date",first.plusDays(block*7+index++/3).toString());String valid=json.writeValueAsString(tree);client.responses.add(withoutRole(valid,"new-side"));client.responses.add(valid);
   var req=new GeminiPeriodService.Request(UUID.randomUUID(),first.plusDays(block*7),7,List.of("breakfast","lunch","dinner"),criteria(List.of()),false,true,List.of());var result=service.generate(1,req,Map.of());count+=result.slots().size();assertEquals(first.plusDays(block*7+6).toString(),result.slots().getLast().date());
  }
  assertEquals(84,count);assertEquals(8,client.calls);assertEquals(4,jdbc.queryForObject("SELECT COUNT(*) FROM gemini_period_requests WHERE status='DONE'",Integer.class));
 }

