 @Test void shortStoredAliasesResolveToCanonicalHashesAndKeepMyRecipePrivate(){
  var recipe=new MyRecipeService.Snapshot("시금치나물",1,10,List.of("시금치 50g"),List.of("무친다."));String data=json.writeValueAsString(recipe),canonical=MyRecipeService.fingerprint(data);jdbc.update("INSERT INTO recipe_library(recipe_id,recipe_data,period_kind) VALUES(?,?,?)",canonical,data,"side");jdbc.update("INSERT INTO my_recipes VALUES(?,?,?)",1,canonical,"PRIVATE-OVERRIDE");var root=json.readTree(client.output);compositionNode(root.path("slots").path(0)).putArray("sideRecipeIds").add("saved-1");client.output=json.writeValueAsString(root);var result=service.generate(1,request(UUID.randomUUID(),1,List.of("breakfast")),Map.of());var input=json.readTree(client.input);assertEquals("saved-1",input.path("recipes").path(0).path("id").asText());assertEquals("saved-1",input.path("savedRecipeIds").path(0).asText());assertFalse(client.input.contains(canonical));assertFalse(client.input.contains("PRIVATE-OVERRIDE"));assertEquals(canonical,result.slots().getFirst().recipeIds().getLast());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM recipe_library WHERE recipe_id LIKE 'saved-%'",Integer.class));
 }
 @Test void allFiveMarchBlocksValidateAfterReferenceRepairIncludingLastThreeDays(){
  LocalDate first=LocalDate.of(2027,3,1);int count=0;for(int block=0;block<5;block++){int days=Math.min(7,31-block*7);var root=json.readTree(output(days,List.of("breakfast","lunch","dinner")));int index=0;for(var row:root.path("slots"))((tools.jackson.databind.node.ObjectNode)row).put("date",first.plusDays(block*7+index++/3).toString());String valid=json.writeValueAsString(root);compositionNode(root.path("slots").path(Math.min(4,days*3-1))).putArray("sideRecipeIds").add("new-undefined");client.responses.add(json.writeValueAsString(root));client.responses.add(valid);var req=new GeminiPeriodService.Request(UUID.randomUUID(),first.plusDays(block*7),days,List.of("breakfast","lunch","dinner"),criteria(List.of()),false,true,List.of());var result=service.generate(1,req,Map.of());count+=result.slots().size();assertEquals(first.plusDays(block*7+days-1).toString(),result.slots().getLast().date());}assertEquals(93,count);assertEquals(10,client.calls);
 }

 GeminiPeriodService.FixedDish fixed(String id,String role,String name,String ingredient){return new GeminiPeriodService.FixedDish(id,role,new MyRecipeService.Snapshot(name,1,0,List.of(ingredient),List.of("사용자가 선택한 음식과 먹을 분량을 유지한다.")));}
 GeminiPeriodService.Request single(UUID id,List<GeminiPeriodService.FixedDish> fixed){return new GeminiPeriodService.Request(id,LocalDate.of(2026,11,15),1,List.of("breakfast"),criteria(List.of()),false,true,List.of(),fixed);}
 String anchoredOutput(String payload,String center,String staple,String side){var root=json.readTree(payload);for(var slot:root.path("slots")){var c=compositionNode(slot);((tools.jackson.databind.node.ObjectNode)c.path("center")).put("recipeId",center);c.put("stapleRecipeId",staple);c.putArray("sideRecipeIds").add(side);}return json.writeValueAsString(root);}
